<?php
require_once __DIR__.'/_auth.php';require_once __DIR__.'/_layout.php';require_once __DIR__.'/_producao.php';
$db=db();$error='';$osId=(int)($_GET['os']??$_POST['os_id']??0);$ready=prodReady($db);
if($_SERVER['REQUEST_METHOD']==='POST') {
    csrfVerify();$action=$_POST['action']??'';
    try {
        if($action==='instalar') {
            if(perfilAtual()!=='admin'){http_response_code(403);exit('Acesso exclusivo do administrador.');}
            foreach(require __DIR__.'/_producao_schema.php' as $sql)$db->exec($sql);
            redirect('/admin/producao.php?saved=1');
        }
        if(!$ready)throw new InvalidArgumentException('Ative a estrutura de produção primeiro.');
        if($action==='criar_os') {
            prodRequireManager();
            if(!isset($_POST['confirmar_aprovacao']))throw new InvalidArgumentException('Confirme a aprovação do cliente antes de abrir a OS.');
            $numero=prodTexto($_POST,'numero',50,true);$cliente=prodTexto($_POST,'cliente',255,true);$titulo=prodTexto($_POST,'titulo',255,true);
            $proposta=(int)($_POST['proposta_id']??0);
            if($proposta){$s=$db->prepare('SELECT id FROM propostas WHERE id=?');$s->execute([$proposta]);if(!$s->fetch())throw new InvalidArgumentException('Proposta não encontrada.');}
            $db->beginTransaction();$db->prepare('INSERT INTO producao_os(numero,cliente,titulo,proposta_id,aprovacao,prazo,created_by) VALUES(?,?,?,?,?,?,?)')->execute([$numero,$cliente,$titulo,$proposta?:null,prodData($_POST['aprovacao']??'',true),prodData($_POST['prazo']??''),$_SESSION['user_id']]);$id=(int)$db->lastInsertId();prodAudit($db,'abrir_os',$id,null,null,['numero'=>$numero,'cliente'=>$cliente,'titulo'=>$titulo,'proposta_id'=>$proposta]);$db->commit();redirect('/admin/producao.php?os='.$id.'&saved=1');
        }
        $s=$db->prepare('SELECT * FROM producao_os WHERE id=?');$s->execute([$osId]);if(!$s->fetch())throw new InvalidArgumentException('OS não encontrada.');
        if($action==='salvar_peca')prodSalvarPeca($db,$_POST,$osId);
        elseif($action==='adicionar_peca') {
            prodRequireManager();$dados=prodPecaDados($db,$_POST);$etapas=prodEtapas([]);
            $db->beginTransaction();$id=prodInserirPeca($db,$osId,$dados,'pendente',$etapas);prodAudit($db,'adicionar_peca',$osId,$id,null,['dados'=>$dados,'status'=>'pendente']);$db->commit();
        } else throw new InvalidArgumentException('Ação inválida.');
        redirect('/admin/producao.php?os='.$osId.'&saved=1');
    }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'Não foi possível concluir. Confira se o número da OS já existe e tente novamente.';error_log('[Axion produção] '.$e->getMessage());}
}
$manager=podeGerenciarProducao();
layout_start('Produção / PCP','producao');
?>
<link rel="stylesheet" href="/css/producao.css?v=20261019-ui2">
<?php if($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif ?>
<?php if(isset($_GET['saved'])): ?><div class="alert alert-success">Salvo com sucesso. A alteração foi registrada no histórico.</div><?php endif ?>
<?php if(!$ready): ?>
<div class="card"><div class="card-title">Ativar módulo de produção</div><p>A estrutura será acrescentada ao banco sem apagar dados existentes. Os usuários atuais continuam como administradores.</p><?php if(perfilAtual()==='admin'): ?><form method="POST" style="margin-top:16px"><?= csrfField() ?><input type="hidden" name="action" value="instalar"><button class="btn btn-primary" type="submit">Criar estrutura de produção</button></form><?php else: ?><p>Solicite a ativação ao administrador.</p><?php endif ?></div>
<?php layout_end();exit;endif ?>
<?php if(!$osId):
$orders=$db->query("SELECT o.*,COUNT(p.id) AS pecas,COALESCE(SUM(p.quantidade*p.peso_unitario),0) AS peso FROM producao_os o LEFT JOIN producao_pecas p ON p.os_id=o.id GROUP BY o.id ORDER BY o.id DESC")->fetchAll();
$propostas=$manager?$db->query('SELECT id,numero,cliente_nome FROM propostas ORDER BY id DESC LIMIT 300')->fetchAll():[];
?>
<?php if($manager): ?><details class="card"><summary class="prod-summary">Abrir OS após aprovação do cliente</summary><form method="POST" class="frow prod-edit-form" style="margin-top:16px"><?= csrfField() ?><input type="hidden" name="action" value="criar_os">
<div class="fg"><label>Número da OS</label><input name="numero" required maxlength="50"></div><div class="fg"><label>Cliente</label><input name="cliente" required maxlength="255"></div><div class="fg"><label>Descrição da obra / serviço</label><input name="titulo" required maxlength="255"></div><div class="fg"><label>Orçamento de origem (opcional)</label><select name="proposta_id"><option value="">Sem vínculo</option><?php foreach($propostas as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['numero'].' — '.$p['cliente_nome']) ?></option><?php endforeach ?></select></div><div class="fg"><label>Data da aprovação</label><input type="date" name="aprovacao" required></div><div class="fg"><label>Prazo de entrega</label><input type="date" name="prazo"></div><label><input type="checkbox" name="confirmar_aprovacao" required> Cliente aprovou o orçamento</label><div><button class="btn btn-primary">Abrir OS</button></div></form></details><?php endif ?>
<div class="card"><div class="card-title">Ordens de serviço</div><?php if(!$orders): ?><p>Nenhuma OS cadastrada.</p><?php else: ?><div class="prod-scroll"><table><thead><tr><th>OS</th><th>Cliente / serviço</th><th>Prazo</th><th>Itens</th><th>Peso total</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= e($o['numero']) ?></td><td><?= e($o['cliente']) ?><div class="td-sub"><?= e($o['titulo']) ?></div></td><td><?= e($o['prazo']?:'Não definido') ?></td><td><?= (int)$o['pecas'] ?></td><td><?= number_format((float)$o['peso'],3,',','.') ?> kg</td><td><a href="?os=<?= (int)$o['id'] ?>" class="btn btn-secondary btn-sm">Abrir produção</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div>
<?php else:
$s=$db->prepare('SELECT * FROM producao_os WHERE id=?');$s->execute([$osId]);$os=$s->fetch();if(!$os){echo '<div class="card">OS não encontrada.</div>';layout_end();exit;}
$rows=prodFiltros($db,$osId,$_GET);$all=prodFiltros($db,$osId,[]);$totalG=0;$filteredG=0;$weighted=0;
foreach($all as $p){$g=prodPesoGramas((string)$p['peso_unitario'])*(int)$p['quantidade'];$totalG+=$g;$weighted+=$g*prodAvanco(json_decode($p['etapas'],true));}
foreach($rows as $p)$filteredG+=prodPesoGramas((string)$p['peso_unitario'])*(int)$p['quantidade'];
$people=$db->query('SELECT u.id,u.username FROM users u LEFT JOIN user_perfis p ON p.user_id=u.id WHERE COALESCE(p.ativo,1)=1 ORDER BY u.username')->fetchAll();
$edit=null;if((int)($_GET['edit']??0)){ $s=$db->prepare('SELECT * FROM producao_pecas WHERE id=? AND os_id=?');$s->execute([(int)$_GET['edit'],$osId]);$edit=$s->fetch()?:null; }
$s=$db->prepare('SELECT * FROM producao_arquivos WHERE os_id=? ORDER BY id DESC');$s->execute([$osId]);$files=$s->fetchAll();
?>
<a class="btn btn-ghost btn-sm" href="/admin/producao.php">← Ordens de serviço</a>
<div class="card" style="margin-top:16px"><div class="card-title">OS <?= e($os['numero'].' — '.$os['titulo']) ?></div><p><?= e($os['cliente']) ?> · Aprovada em <?= e($os['aprovacao']) ?> · Prazo <?= e($os['prazo']?:'não definido') ?></p></div>
<div class="kpi-grid"><div class="kpi"><div class="kpi-label">Peso total da lista</div><div class="kpi-val mono"><?= number_format($totalG/1000,3,',','.') ?> kg</div></div><div class="kpi"><div class="kpi-label">Peso do filtro · <?= count($rows) ?> itens</div><div class="kpi-val mono"><?= number_format($filteredG/1000,3,',','.') ?> kg</div></div><div class="kpi"><div class="kpi-label">Peso selecionado</div><div class="kpi-val mono" data-prod-peso>0,000 kg</div></div><div class="kpi"><div class="kpi-label">Avanço da OS por peso</div><div class="kpi-val mono"><?= number_format($totalG?$weighted/$totalG:0,2,',','.') ?>%</div></div></div>
<?php if($manager): ?><div class="card"><div class="card-title">Planilha de fabricação</div><p style="margin-bottom:14px">Importe a planilha Excel para cadastrar as peças, conferir os pesos e acompanhar a fabricação.</p><a class="btn btn-primary" href="/admin/producao_importar.php?os=<?= $osId ?>">Importar planilha de fabricação (.xlsx)</a><p class="text-muted" style="margin-top:12px">Para guardar o arquivo original como anexo da OS, envie XLSX, XLS ou CSV em Documentos e planilhas abaixo.</p></div><?php endif ?>
<details class="card"><summary class="prod-summary">Documentos e planilhas do cliente (<?= count($files) ?>)</summary><ul class="prod-files"><?php foreach($files as $file): ?><li><a href="/admin/producao_arquivo.php?id=<?= (int)$file['id'] ?>"><?= e($file['nome']) ?></a> <span class="text-muted"><?= e($file['created_at']) ?></span></li><?php endforeach ?></ul><?php if($manager): ?><form method="POST" enctype="multipart/form-data" action="/admin/producao_arquivo.php" class="prod-upload-form"><?= csrfField() ?><input type="hidden" name="os_id" value="<?= $osId ?>"><div class="fg"><label>Planilha (XLSX, XLS, CSV), PDF, imagem, DWG ou DXF · até 20 MB</label><input type="file" name="arquivo" accept=".xlsx,.xls,.csv,.pdf,.png,.jpg,.jpeg,.dwg,.dxf" required></div><div class="prod-upload-action"><button class="btn btn-secondary">Anexar documento</button></div></form><a class="btn btn-secondary btn-sm" href="/admin/producao_importar.php?os=<?= $osId ?>" style="margin-top:12px">Importar lista de fabricação (.xlsx)</a><?php endif ?></details>
