<details class="card" id="editar" <?= $edit?'open':'' ?>><summary class="prod-summary"><?= $edit?'Editar peça #'.(int)$edit['id']:'Adicionar peça manualmente' ?></summary><form method="POST" class="frow prod-edit-form" style="margin-top:16px"><?= csrfField() ?><input type="hidden" name="action" value="<?= $edit?'salvar_peca':'adicionar_peca' ?>"><input type="hidden" name="os_id" value="<?= $osId ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="versao" value="<?= (int)($edit['versao']??0) ?>">
<?php if($manager): ?>
<?php foreach(['data'=>['Data','date',null],'avulsas'=>['Avulsas','text',100],'descricao'=>['Descrição do material','text',255],'tag'=>['TAG','text',150],'desenho'=>['Nº desenho','text',255],'revisao'=>['Revisão do desenho','text',30],'quantidade'=>['Quantidade','number',null],'peso_unitario'=>['Peso de cada peça (kg)','number',null],'romaneio'=>['Nº romaneio','text',100]] as $key=>[$label,$type,$max]): ?><div class="fg"><label><?= $label ?></label><input type="<?= $type ?>" name="<?= $key ?>" value="<?= e((string)($edit[$key]??($key==='quantidade'?'1':($key==='peso_unitario'?'0':'')))) ?>" <?= $max?'maxlength="'.$max.'"':'' ?> <?= in_array($key,['descricao','quantidade','peso_unitario'])?'required':'' ?> <?= $key==='quantidade'?'min="1" max="1000000" step="1"':'' ?> <?= $key==='peso_unitario'?'min="0" max="9999999.999" step="0.001"':'' ?>></div><?php endforeach ?>
