<?php else: ?><p class="prod-wide"><?= e($edit['descricao'].' · '.$edit['tag'].' · '.$edit['desenho']) ?>. Você pode atualizar status e avanço; os demais dados são gerenciados pelo PCP.</p><?php endif ?>
