<?php foreach(PROD_ETAPAS as $key=>[$label,$weight]): ?><div class="fg"><label><?= $label ?> · peso <?= $weight ?>%</label><select name="etapas[<?= $key ?>]"><?php foreach([0,25,50,75,100] as $percent): ?><option value="<?= $percent ?>" <?= (int)$e[$key]===$percent?'selected':'' ?>><?= $percent ?>%</option><?php endforeach ?></select></div><?php endforeach ?>
